 proof fn lemma_filter_first_is_subrange<K>(s: Seq<K>)
     requires
         s.no_duplicates(),
         s.len() > 0,
     ensures
         s.filter(|k: K| k != s[0]) =~= s.subrange(1, s.len() as int),
