         // 1. no_duplicates for the subranged lru_order
         lemma_subrange_no_dup(old_lru, 1, old_lru.len() as int);

         // 2. to_set: subrange(1, len).to_set() == to_set().remove(s[0])
         lemma_drop_first_to_set(old_lru);

