479. /// Uses filter_distributes_over_add to split s = [first] + tail, then shows:
480. ///   - filter([first]) = empty (pred rejects first)
481. ///   - filter(tail) = tail (no element equals first, by no_duplicates)
482. proof fn lemma_filter_neq_first_is_subrange<K>(s: Seq<K>, first: K)
483.     requires
484.         s.no_duplicates(),
485.         s.len() > 0,
486.         s[0] == first,
487.     ensures
488.         s.filter(|k: K| k != first) =~= s.subrange(1, s.len() as int),
489. {
490.     let pred = |k: K| k != first;
491.     let n = s.len() as int;
492.     let head = s.subrange(0, 1);
493.     let tail = s.subrange(1, n);
494. 
495.     // Step 1: s == head + tail
496.     s.lemma_split_at(1);
497.     assert(head + tail =~= s);
498. 
499.     // Step 2: filter distributes over concatenation
500.     Seq::filter_distributes_over_add(head, tail, pred);
501.     // Now: (head + tail).filter(pred) == head.filter(pred) + tail.filter(pred)
502. 
503.     // Step 3: head.filter(pred) == empty
504.     // head = [first], pred(first) == false
505.     assert(head[0] == first);
506.     assert(!pred(first));
507.     assert(head.filter(pred) =~= Seq::<K>::empty()) by {
508.         reveal_with_fuel(Seq::filter, 2);
509.     };
510. 
511.     // Step 4: tail.filter(pred) == tail (all elements differ from first)
512.     assert forall |i: int| 0 <= i < tail.len() implies #[trigger] tail[i] != first by {
513.         assert(tail[i] == s[1 + i]);  // subrange indexing
514.         // s.no_duplicates(): indices 0 and 1+i are distinct, so s[0] != s[1+i]
515.     };
516.     assert(!tail.contains(first));
517.     lemma_filter_neq_absent(tail, first);
518.     // tail.filter(pred) =~= tail
519. 
520.     // Step 5: combine
521.     assert(Seq::<K>::empty() + tail =~= tail);
522.     // s.filter(pred) == (head + tail).filter(pred) == empty + tail == tail == s.subrange(1, n)
523. }
